namespace sv_4400a3f8842f4005ae164ad324d40c17.Models;

public sealed class Recipe
{
    public required int Id { get; init; }
    public required string Title { get; init; }
    public required string Description { get; init; }
    public required int PrepTimeMinutes { get; init; }
}

using sv_4400a3f8842f4005ae164ad324d40c17.Models;

namespace sv_4400a3f8842f4005ae164ad324d40c17.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new() { Id = 1, Title = "Margherita Pizza", Description = "Classic Neapolitan pizza with fresh mozzarella, basil, and San Marzano tomatoes.", PrepTimeMinutes = 30 },
            new() { Id = 2, Title = "Cacio e Pepe", Description = "Roman pasta with Pecorino Romano and black pepper.", PrepTimeMinutes = 20 },
            new() { Id = 3, Title = "Tiramisu", Description = "Layered coffee-soaked ladyfingers with mascarpone cream.", PrepTimeMinutes = 45 },
            new() { Id = 4, Title = "Risotto alla Milanese", Description = "Creamy saffron-infused risotto from Milan.", PrepTimeMinutes = 40 },
        },
        [2] = new List<Recipe>
        {
            new() { Id = 5, Title = "Pad Thai", Description = "Stir-fried rice noodles with shrimp, peanuts, and tamarind sauce.", PrepTimeMinutes = 25 },
            new() { Id = 6, Title = "Green Curry", Description = "Aromatic coconut-based curry with Thai basil and vegetables.", PrepTimeMinutes = 35 },
            new() { Id = 7, Title = "Tom Yum Soup", Description = "Hot and sour soup with lemongrass, galangal, and prawns.", PrepTimeMinutes = 20 },
        },
        [3] = new List<Recipe>
        {
            new() { Id = 8, Title = "Tacos al Pastor", Description = "Marinated pork tacos with pineapple and cilantro.", PrepTimeMinutes = 50 },
            new() { Id = 9, Title = "Guacamole", Description = "Fresh avocado dip with lime, onion, and jalapeño.", PrepTimeMinutes = 10 },
            new() { Id = 10, Title = "Enchiladas Verdes", Description = "Corn tortillas filled with chicken, topped with green salsa.", PrepTimeMinutes = 40 },
            new() { Id = 11, Title = "Churros", Description = "Fried dough pastries dusted with cinnamon sugar.", PrepTimeMinutes = 30 },
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow API call.
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@using sv_4400a3f8842f4005ae164ad324d40c17.Models
@using sv_4400a3f8842f4005ae164ad324d40c17.Services
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_error</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <div class="alert alert-info py-1 px-2 d-inline-block" role="status">Refreshing…</div>
    }

    var displayed = GetSortedRecipes();

    @if (displayed.Count == 0)
    {
        <p>No recipes found for this cuisine.</p>
    }
    else
    {
        <table class="table">
            <thead>
                <tr>
                    <th>Title</th>
                    <th>Description</th>
                    <th>Prep Time</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var recipe in displayed)
                {
                    <tr>
                        <td>@recipe.Title</td>
                        <td>@recipe.Description</td>
                        <td>@recipe.PrepTimeMinutes min</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private string? _error;
    private bool _isRefreshing;
    private int _loadedCuisineId;
    private CancellationTokenSource? _loadCts;
    private bool _disposed;

    protected override Task OnInitializedAsync()
    {
        // Capture the initial cuisine so OnParametersSetAsync sees it as a change.
        _loadedCuisineId = -1;
        return Task.CompletedTask;
    }

    protected override async Task OnParametersSetAsync()
    {
        // Sort-only changes should not reload data.
        if (CuisineId == _loadedCuisineId)
        {
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request for the previous cuisine.
        await CancelPendingLoadAsync();

        _loadedCuisineId = CuisineId;
        _error = null;
        _isRefreshing = _recipes is not null;

        var cts = CancellationTokenSource.CreateLinkedTokenSource(default);
        _loadCts = cts;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            if (!cts.Token.IsCancellationRequested)
            {
                _recipes = result;
                _isRefreshing = false;
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when the user navigated to a different cuisine or away from the page.
        }
        catch (TimeoutException ex)
        {
            if (!cts.Token.IsCancellationRequested)
            {
                Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
                _error = "The request timed out. Please try again.";
                _isRefreshing = false;
            }
        }
        catch (Exception ex)
        {
            if (!cts.Token.IsCancellationRequested)
            {
                Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
                _error = "Something went wrong while loading recipes. Please try again.";
                _isRefreshing = false;
            }
        }
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync();
    }

    private List<Recipe> GetSortedRecipes()
    {
        if (_recipes is null)
        {
            return new List<Recipe>();
        }

        return Sort?.ToLowerInvariant() switch
        {
            "newest" => _recipes.OrderByDescending(r => r.Id).ToList(),
            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes).ToList(),
            _ => _recipes,
        };
    }

    private async ValueTask CancelPendingLoadAsync()
    {
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_disposed)
        {
            return;
        }

        _disposed = true;
        await CancelPendingLoadAsync();
    }
}

