+    <div class="alert alert-danger" role="alert">
+        <p>@_error</p>
+        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
+    </div>
+}
+else if (_recipes is null)
+{
+    <p><em>Loading recipes…</em></p>
+}
+else
+{
+    @if (_isRefreshing)
+    {
+        <div class="alert alert-info py-1 px-2 d-inline-block" role="status">Refreshing…</div>
+    }
+
+    var displayed = GetSortedRecipes();
+
+    @if (displayed.Count == 0)
+    {
+        <p>No recipes found for this cuisine.</p>
+    }
+    else
+    {
+        <table class="table">
+            <thead>
+                <tr>
+                    <th>Title</th>
+                    <th>Description</th>
+                    <th>Prep Time</th>
+                </tr>
+            </thead>
+            <tbody>
+                @foreach (var recipe in displayed)
+                {
+                    <tr>
+                        <td>@recipe.Title</td>
+                        <td>@recipe.Description</td>
+                        <td>@recipe.PrepTimeMinutes min</td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    }
+}
+
+@code {
+    [Parameter]
+    public int CuisineId { get; set; }
+
+    [SupplyParameterFromQuery(Name = "sort")]
+    public string? Sort { get; set; }
+
+    private List<Recipe>? _recipes;
+    private string? _error;
+    private bool _isRefreshing;
+    private int _loadedCuisineId;
+    private CancellationTokenSource? _loadCts;
+    private bool _disposed;
+
+    protected override Task OnInitializedAsync()
+    {
+        // Capture the initial cuisine so OnParametersSetAsync sees it as a change.
+        _loadedCuisineId = -1;
+        return Task.CompletedTask;
+    }
+
+    protected override async Task OnParametersSetAsync()
+    {
+        // Sort-only changes should not reload data.
+        if (CuisineId == _loadedCuisineId)
+        {
+            return;
+        }
+
+        await LoadRecipesAsync();
+    }
+
+    private async Task LoadRecipesAsync()
+    {
+        // Cancel any in-flight request for the previous cuisine.
+        await CancelPendingLoadAsync();
+
+        _loadedCuisineId = CuisineId;
+        _error = null;
+        _isRefreshing = _recipes is not null;
+
+        var cts = CancellationTokenSource.CreateLinkedTokenSource(default);
+        _loadCts = cts;
+
+        try
+        {
+            var result = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);
+
+            if (!cts.Token.IsCancellationRequested)
+            {
+                _recipes = result;
+                _isRefreshing = false;
+            }
+        }
+        catch (OperationCanceledException)
+        {
+            // Expected when the user navigated to a different cuisine or away from the page.
+        }
+        catch (TimeoutException ex)
+        {
+            if (!cts.Token.IsCancellationRequested)
+            {
+                Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
+                _error = "The request timed out. Please try again.";
+                _isRefreshing = false;
+            }
+        }
+        catch (Exception ex)
+        {
+            if (!cts.Token.IsCancellationRequested)
+            {
+                Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
+                _error = "Something went wrong while loading recipes. Please try again.";
+                _isRefreshing = false;
+            }
+        }
+    }
+
+    private async Task RetryAsync()
+    {
+        await LoadRecipesAsync();
+    }
+
+    private List<Recipe> GetSortedRecipes()
+    {
+        if (_recipes is null)
+        {
+            return new List<Recipe>();
+        }
+
+        return Sort?.ToLowerInvariant() switch
+        {
+            "newest" => _recipes.OrderByDescending(r => r.Id).ToList(),
+            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes).ToList(),
+            _ => _recipes,
+        };
+    }
+
+    private async ValueTask CancelPendingLoadAsync()
+    {
+        if (_loadCts is not null)
+        {
+            await _loadCts.CancelAsync();
+            _loadCts.Dispose();
+            _loadCts = null;
+        }
+    }
+
+    public async ValueTask DisposeAsync()
+    {
+        if (_disposed)
+        {
+            return;
+        }
+
+        _disposed = true;
+        await CancelPendingLoadAsync();
+    }
+}
